question:
What does Singleton pattern ensure?
public class Logger {
  private static Logger instance = new Logger();
  private Logger() { }
  public static Logger Instance => instance;
}

What does Factory pattern provide?
public class ShapeFactory {
  public static Shape CreateShape(string type) {
    return type switch {
      "circle" => new Circle(),
      "square" => new Square(),
      _ => throw new ArgumentException()
    };
  }
}

What does Builder pattern enable?
var person = new PersonBuilder()
  .SetName("Alice")
  .SetAge(30)
  .SetEmail("alice@test.com")
  .Build();

What does Observer pattern do?
public class Subject {
  public event Action<string> Changed;
  public void Notify(string message) => Changed?.Invoke(message);
}
var subject = new Subject();
subject.Changed += (msg) => Console.WriteLine(msg);

What does Strategy pattern define?
public interface PaymentStrategy {
  void Pay(decimal amount);
}
public class CreditCardPayment : PaymentStrategy {
  public void Pay(decimal amount) { }
}
public class PayPalPayment : PaymentStrategy {
  public void Pay(decimal amount) { }
}

What does Decorator pattern add?
public abstract class Component { public abstract void Operation(); }
public class Decorator : Component {
  protected Component component;
  public override void Operation() => component.Operation();
}

What does Adapter pattern do?
public interface NewInterface {
  void NewMethod();
}
public class OldClass {
  public void OldMethod() { }
}
public class Adapter : NewInterface {
  private OldClass old = new OldClass();
  public void NewMethod() => old.OldMethod();
}

What does Template Method pattern define?
public abstract class Algorithm {
  public void Execute() {
    Setup();
    Process();
    Cleanup();
  }
  protected abstract void Process();
  protected virtual void Setup() { }
  protected virtual void Cleanup() { }
}

What does Facade pattern provide?
public class DatabaseFacade {
  public void InitializeDatabase() {
    ConnectToDB();
    LoadSchema();
    ValidateConnections();
  }
}

What does Chain of Responsibility pattern do?
public abstract class Handler {
  protected Handler next;
  public virtual void Handle(Request req) {
    if (CanHandle(req)) ProcessRequest(req);
    else next?.Handle(req);
  }
  protected abstract bool CanHandle(Request req);
}
